INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3137607, 440311, 14476, '<td valign="top">Interesting.  You have, by your composition, and excellent DOF, made the mundane into a handsome work of art.  Yep.  A 10.</td>', 'Interesting.  You have, by your composition, and excellent DOF, made the mundane into a handsome work of art.  Yep.  A 10.', '2006-12-20 23:23:00.000000', NULL, 1),
(3137612, 439720, 14476, '<td valign="top">Nice composition.  Nice background colors.  Maybe just a little more excitement in the image would put this well up in the standings.  (Reeds and grasses are FUN)</td>', 'Nice composition.  Nice background colors.  Maybe just a little more excitement in the image would put this well up in the standings.  (Reeds and grasses are FUN)', '2006-12-20 23:24:56.000000', NULL, 1),
(3137616, 440450, 14476, '<td valign="top">Awww, gee.  These horse pics will get to me every time.  This beauty is caught nicely.  Maybe just a little more room to run would bring this Wild Chestnut to the first tier.  Still, It''s a suberb shot.  (wish it was mine)</td>', 'Awww, gee.  These horse pics will get to me every time.  This beauty is caught nicely.  Maybe just a little more room to run would bring this Wild Chestnut to the first tier.  Still, It''s a suberb shot.  (wish it was mine)', '2006-12-20 23:27:16.000000', NULL, 1),
(3137619, 440193, 14476, '<td valign="top">When I think of Maui, I think of lush greens and blues.  It''s hard to make the transition to sepia.</td>', 'When I think of Maui, I think of lush greens and blues.  It''s hard to make the transition to sepia.', '2006-12-20 23:28:47.000000', NULL, 1),
