(3137625, 439363, 69573, '<td valign="top">sweet</td>', 'sweet', '2006-12-20 23:34:02.000000', NULL, 1),
(3137628, 438198, 14476, '<td valign="top">The story revealed in this image is strong.  Execution?<br/>Frankly, I''m not qualified to make a judgement.  <br/>All I can say, is "I admire it and wish it was mine."<br/>All I can do is say, thank you.  10</td>', 'The story revealed in this image is strong.  Execution?Frankly, I''m not qualified to make a judgement.  All I can say, is "I admire it and wish it was mine."All I can do is say, thank you.  10', '2006-12-20 23:34:58.000000', NULL, 1),
