(3149834, 440111, 70270, '<td valign="top">Nicely put together, and great sense of humor</td>', 'Nicely put together, and great sense of humor', '2006-12-26 14:07:46.000000', NULL, 1),
(3149839, 440042, 70270, '<td valign="top">Nice setup.  I would have liked to see it shot from a lower angle, to see more of the boots in the foreground.  My eye kept jumping back and forth between the shoes and their reflection.</td>', 'Nice setup.  I would have liked to see it shot from a lower angle, to see more of the boots in the foreground.  My eye kept jumping back and forth between the shoes and their reflection.', '2006-12-26 14:10:05.000000', NULL, 1),
