(3149842, 438344, 70270, '<td valign="top">I love the contrast in colors and orientation between the leaves.  nice shot.</td>', 'I love the contrast in colors and orientation between the leaves.  nice shot.', '2006-12-26 14:12:33.000000', NULL, 1),
(3149865, 439724, 70056, '<td valign="top">My only problems with this photo is you focused on your subjects lips, not their eyes, and that also made you hand oversaturated with light.</td>', 'My only problems with this photo is you focused on your subjects lips, not their eyes, and that also made you hand oversaturated with light.', '2006-12-26 14:22:35.000000', NULL, 1),
(3149868, 440482, 70056, '<td valign="top">... thats a lot of bread! Sorry, nothing useful in this comment, carry on.</td>', '... thats a lot of bread! Sorry, nothing useful in this comment, carry on.', '2006-12-26 14:23:56.000000', NULL, 1),
(3149873, 438735, 70056, '<td valign="top">I would have liked it better if you had used the guitar as the background, and had the focus be on the end of the guitar, and not on the tuning knobs (for lack of a better term... obviously not a guitar player.)</td>', 'I would have liked it better if you had used the guitar as the background, and had the focus be on the end of the guitar, and not on the tuning knobs (for lack of a better term... obviously not a guitar player.)', '2006-12-26 14:26:17.000000', NULL, 1),
(3149875, 440285, 70056, '<td valign="top">Not bad. Hard picture to take in that lighting. Little blurry, but it gets the point across.</td>', 'Not bad. Hard picture to take in that lighting. Little blurry, but it gets the point across.', '2006-12-26 14:27:03.000000', NULL, 1),
(3149878, 440505, 70056, '<td valign="top">not exactly clear what it is, and not exactly clear at all. Little too blurry for a good macro shot.</td>', 'not exactly clear what it is, and not exactly clear at all. Little too blurry for a good macro shot.', '2006-12-26 14:28:28.000000', NULL, 1),
(3149882, 440537, 70056, '<td valign="top">Good picture. I don''t particularly like the tongue, however I can see why you did it, so thats just a personal preference. Nice lighting however.</td>', 'Good picture. I don''t particularly like the tongue, however I can see why you did it, so thats just a personal preference. Nice lighting however.', '2006-12-26 14:29:29.000000', NULL, 1),
(3149885, 440510, 70056, '<td valign="top">That dog is black. His ear is slightly brown, but not really enough. The lighting is poor, although it gives a decent mood. All in all, an okay picture, but sort of dull.</td>', 'That dog is black. His ear is slightly brown, but not really enough. The lighting is poor, although it gives a decent mood. All in all, an okay picture, but sort of dull.', '2006-12-26 14:31:40.000000', NULL, 1),
(3149886, 438514, 42100, '<td valign="top">Wonderful studio portrait of the pup, yours I assume.  Very beautiful dog and a great photograph!</td>', 'Wonderful studio portrait of the pup, yours I assume.  Very beautiful dog and a great photograph!', '2006-12-26 14:32:35.000000', NULL, 1),
(3149887, 440382, 70056, '<td valign="top">Decent depth of field shot... not the right thing or the right amount of it is focus however.</td>', 'Decent depth of field shot... not the right thing or the right amount of it is focus however.', '2006-12-26 14:32:37.000000', NULL, 1),
(3149888, 439507, 70056, '<td valign="top">Nice depth of field shot. Right thing to be in focus.</td>', 'Nice depth of field shot. Right thing to be in focus.', '2006-12-26 14:33:18.000000', NULL, 1),
