(3149901, 440612, 59415, '<td valign="top">The detail is amazing. Very nice splash photo.</td>', 'The detail is amazing. Very nice splash photo.', '2006-12-26 14:47:46.000000', NULL, 1),
(3149902, 440646, 59415, '<td valign="top">Ha!  Classic humor.  Good thing Ozzy likes them or they might not even be around.</td>', 'Ha!  Classic humor.  Good thing Ozzy likes them or they might not even be around.', '2006-12-26 14:48:19.000000', NULL, 1),
