(3149905, 440504, 59415, '<td valign="top">Very cool tones on this one.  Seems to have a touch of over-neat/ninja going.  Just distracts me a bit but overall a stunning image. 8</td>', 'Very cool tones on this one.  Seems to have a touch of over-neat/ninja going.  Just distracts me a bit but overall a stunning image. 8', '2006-12-26 14:49:44.000000', NULL, 1),
