(3149920, 439994, 59415, '<td valign="top">I like the angle and the contrast of the silver and the brown.  Very cool.</td>', 'I like the angle and the contrast of the silver and the brown.  Very cool.', '2006-12-26 14:57:39.000000', NULL, 1),
(3149922, 440405, 59415, '<td valign="top">Very nice detail, great lighting and super cool tone. 8</td>', 'Very nice detail, great lighting and super cool tone. 8', '2006-12-26 14:58:34.000000', NULL, 1),
(3149923, 440169, 59415, '<td valign="top">This is exactly what I would like to be doing right now.  I think this is a great pet photo. 8</td>', 'This is exactly what I would like to be doing right now.  I think this is a great pet photo. 8', '2006-12-26 14:59:16.000000', NULL, 1),
