(3149927, 440511, 59415, '<td valign="top">The light is a bit harsh on the one cheek, but the tones are spectacular.  Also the shadow on his left cheek is a bit awkward.  A little more post with a few tweaks and you would have a contending image.</td>', 'The light is a bit harsh on the one cheek, but the tones are spectacular.  Also the shadow on his left cheek is a bit awkward.  A little more post with a few tweaks and you would have a contending image.', '2006-12-26 15:02:49.000000', NULL, 1),
(3149928, 440518, 59415, '<td valign="top">Love the candid, and don''t worry it will grow back.</td>', 'Love the candid, and don''t worry it will grow back.', '2006-12-26 15:03:35.000000', NULL, 1),
(3149929, 438735, 59415, '<td valign="top">I think a tighter shot might have yielded a higher score.  I give it a 6.</td>', 'I think a tighter shot might have yielded a higher score.  I give it a 6.', '2006-12-26 15:04:12.000000', NULL, 1),
