INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3156248, 440324, 69939, '<td valign="top">Almost like a painting. Great shot.</td>', 'Almost like a painting. Great shot.', '2006-12-28 13:29:32.000000', NULL, 0),
